fragment.source:
mat2 turn(float a){return mat2(cos(a),-sin(a),sin(a),cos(a));}
vec3 finish(vec3 c){return 1.0-exp(-max(c,vec3(0.0)));}
// Time-only rotations and phase offsets, prepared once per pixel.
mat2 gSpinA,gSpinB;
vec2 gF1,gF2,gF3,gF4,gF5,gF6,gF7,gF8;
float gTwist,gLobeZ,gCrossR;
// p is already in the spinning frame: the two time rotations are applied once per ray.
float metalForm(vec3 p){
 p.xy=turn(p.z*gTwist)*p.xy;
 // Angles enter only through sin/cos of small multiples; expand them from the direction.
 float r=length(p.xy);
 vec2 a1=r>1e-7?p.xy/r:vec2(1.0,0.0);
 vec2 a2=vec2(a1.x*a1.x-a1.y*a1.y,2.0*a1.x*a1.y);
 vec2 a3=vec2(a2.x*a1.x-a2.y*a1.y,a2.y*a1.x+a2.x*a1.y);
 float knot=.61+.22*(a3.x*gF1.x+a3.y*gF1.y)+.10*(a2.x*gF2.x-a2.y*gF2.y)+.07*sin(p.z*3.5+gLobeZ);
 float lift=.25*(a3.y*gF3.x-a3.x*gF3.y)+.12*(a1.y*gF4.x+a1.x*gF4.y);
 float section=uParam_mass*(.86+.23*(a2.x*gF5.x+a2.y*gF5.y)+.12*(a3.y*gF6.x-a3.x*gF6.y));
 float ring=length(vec2(r-knot,p.z-lift))-section;
 // The inner ring stays within gCrossR of the origin; when it is .10 farther
 // than the outer ring the smooth union returns the outer ring unchanged.
 if(length(p)-gCrossR>ring+.10)return ring;
 float q=length(p.xz);
 vec2 b1=q>1e-7?vec2(p.x,p.z)/q:vec2(1.0,0.0);
 vec2 b2=vec2(b1.x*b1.x-b1.y*b1.y,2.0*b1.x*b1.y);
 float inner=.47+.085*(b2.x*gF7.x-b2.y*gF7.y);
 float crossRing=length(vec2(q-inner,p.y-.12*(b2.y*gF8.x-b2.x*gF8.y)-uParam_sweep*.26*(b1.x*.92106099-b1.y*.38941834)))-.105;
 float blend=clamp(.5+.5*(crossRing-ring)/.10,0.,1.);
 return mix(crossRing,ring,blend)-.10*blend*(1.-blend);
}
vec3 metalEnv(vec3 r,float t){
 r.xz=turn(uParam_sweep*.8+t*.045)*r.xz;
 float soft=mix(.18,.04,clamp(uParam_polish/1.2,0.,1.));
 float key=1.0-smoothstep(.24,.24+soft,abs(r.x+.24));
 key*=smoothstep(-.5,.0,r.y);
 float strip=1.0-smoothstep(.045,.045+soft*.5,abs(r.x-.66));
 strip*=smoothstep(-.6,-.2,r.y);
 float horizon=1.0-smoothstep(.055,.055+soft,abs(r.y+.16));
 float warm=max(0.,dot(r,normalize(vec3(.3,-.55,.6))));warm*=warm;warm*=warm;warm*=warm;
 float ceiling=smoothstep(.4,.9,r.y)*.12;
 vec3 c=vec3(.0035,.004,.005)+vec3(.85,.92,1.0)*(key*1.7+strip*2.4+horizon*.65+ceiling);
 c+=mix(vec3(.9,.36,.08),uParam_tint.rgb,.8)*warm*1.8;
 return c;
}
// Ray interval inside the finite cylinder x*x+y*y<=R*R, |z|<=H (empty: x>y).
vec2 cylSpan(vec3 o,vec3 d,float R,float H){
 float a=dot(d.xy,d.xy),b=dot(o.xy,d.xy),c=dot(o.xy,o.xy)-R*R;
 float h=b*b-a*c;
 if(h<0.0||a<1e-8)return vec2(1e9,-1e9);
 h=sqrt(h);
 vec2 tc=vec2(-b-h,-b+h)/a;
 float iz=1.0/(abs(d.z)>1e-6?d.z:1e-6);
 vec2 tz=vec2((-H-o.z)*iz,(H-o.z)*iz);
 tz=vec2(min(tz.x,tz.y),max(tz.x,tz.y));
 return vec2(max(tc.x,tz.x),min(tc.y,tz.y));
}
vec2 phasor(float a){return vec2(cos(a),sin(a));}
// Time-only state shared by the main pass and the coarse stage.
void bloomSetup(float t){
 float flow=vrchPhase_flow()*.9+vrchPhase_accent()*2.4;
 gSpinA=turn(t*.28);gSpinB=turn(t*.19+.5);gTwist=.6+uParam_fold*.9;gCrossR=length(vec2(.555,.12+.26*abs(uParam_sweep)))+.105;gLobeZ=flow*.5;
 gF1=phasor(flow*.65);gF2=phasor(flow*.38);gF3=phasor(flow*.43);gF4=phasor(flow*.52);
 gF5=phasor(flow*.57);gF6=phasor(flow*.34);gF7=phasor(flow*.48);gF8=phasor(flow*.37);
}
void mainImage(out vec4 fragColor,in vec2 fragCoord){
 vec2 uv=(2.0*fragCoord-iResolution.xy)/min(iResolution.x,iResolution.y);
 uv/=uParam_size;
 float t=vrchPhase_speed();
 bloomSetup(t);
 vec3 ro=vec3(0.,0.,3.25),rd=normalize(vec3(uv,-2.45));
 vec3 world=rd;
 ro.xz=gSpinA*ro.xz;ro.yz=gSpinB*ro.yz;
 rd.xz=gSpinA*rd.xz;rd.yz=gSpinB*rd.yz;
 // Every surface point lies inside one of two z-aligned cylinders of the
 // spinning frame (twist keeps radius and z): the outer ring and the inner ring.
 float s=uParam_mass*1.21+.03;
 vec2 spanA=cylSpan(ro,rd,1.0+s,.37+s);
 vec2 spanB=cylSpan(ro,rd,length(vec2(.69,.255+.26*abs(uParam_sweep)))+.02,.71);
 float travel=min(spanA.x,spanB.x),exitAt=max(spanA.y,spanB.y);
 bool found=false;float hitD=0.0;
 float disc=exitAt>travel?1.0:-1.0;
 // The coarse stage found a start that no ray of this 4x4 block reaches the metal before.
 travel=max(max(0.0,travel),vrchCoarseData(fragCoord).x);
 if(disc>0.0&&travel<exitAt){
  // Over-relaxed steps; a step that lands inside the metal is taken back and
  // the march continues with the conservative factor.
  float relax=.72,lastTravel=travel;
  for(int i=0;i<112;i++){
   float d=metalForm(ro+travel*rd);
   if(d<0.0&&relax>.5){travel=lastTravel;relax=.44;continue;}
   if(d<.003){found=true;hitD=d;break;}
   lastTravel=travel;
   travel+=max(.0008,d*relax);if(travel>5.5||travel>exitAt)break;
  }
 }
 // Refine the actual surface crossing before reflecting hard studio lights.
 // The first step reuses the march's last sample; later steps keep its slope.
 if(found){
  vec3 q=ro+travel*rd;
  float slope=(metalForm(q+rd*.001)-metalForm(q-rd*.001))/.002;
  bool steep=abs(slope)>.002;
  if(steep)travel-=clamp(hitD/slope,-.025,.025);
  if(steep)travel-=clamp(metalForm(ro+travel*rd)/slope,-.025,.025);
  if(steep)travel-=clamp(metalForm(ro+travel*rd)/slope,-.025,.025);
  if(abs(metalForm(ro+travel*rd))>.0003)found=false;
 }
 vec3 c=vec3(.0018,.0018,.0018);
 if(found){
  vec3 p=ro+travel*rd;vec2 e=vec2(.0005,-.0005);
  // Tetrahedral gradient: four field samples instead of six.
  vec3 n=normalize(e.xyy*metalForm(p+e.xyy)+e.yyx*metalForm(p+e.yyx)+e.yxy*metalForm(p+e.yxy)+e.xxx*metalForm(p+e.xxx));
  float occlusion=0.;
  for(int j=0;j<2;j++){
   float h=.035+.165*float(j);
   occlusion+=(h-metalForm(p+n*h))/(h+ .001)*.32;
  }
  float ao=clamp(1.-occlusion,.22,1.);
  // Back from the spinning frame to the studio frame.
  n.yz=n.yz*gSpinB;n.xz=n.xz*gSpinA;
  rd=world;
  vec3 refl=reflect(rd,n);
  c=metalEnv(refl,t)*ao;
  float ed=1.-max(0.,dot(n,-rd)),edge=ed*ed*ed;
  c+=vec3(.028,.035,.043)*edge;
  float footprint=travel*2.0/(min(iResolution.x,iResolution.y)*uParam_size*2.45);
  float coverage=smoothstep(0.0,sqrt(footprint*10.0),max(0.0,dot(n,-rd)));
  c=mix(vec3(.0018),c,coverage);
 }
 fragColor=vec4(finish(c*uParam_light),1.0);
}

coarse.source:
// One cone per 4x4 block, around the block's centre ray and wide enough for its
// corner rays, marches until the metal could come within the cone.
void vrchCoarse(in vec2 blockOrigin,in float blockSize,out vec4 value){
 bloomSetup(vrchPhase_speed());
 float m=min(iResolution.x,iResolution.y);
 vec2 uv=(2.0*(blockOrigin+.5*blockSize)-iResolution.xy)/m/uParam_size;
 vec3 ro=vec3(0.,0.,3.25),rd=normalize(vec3(uv,-2.45));
 ro.xz=gSpinA*ro.xz;ro.yz=gSpinB*ro.yz;
 rd.xz=gSpinA*rd.xz;rd.yz=gSpinB*rd.yz;
 float s=uParam_mass*1.21+.03;
 vec2 spanA=cylSpan(ro,rd,1.0+s,.37+s);
 vec2 spanB=cylSpan(ro,rd,length(vec2(.69,.255+.26*abs(uParam_sweep)))+.02,.71);
 float entry=min(spanA.x,spanB.x),exitAt=max(spanA.y,spanB.y);
 value=vec4(0.0);
 if(exitAt<=entry)return;
 // Cone half-width per unit distance: the block's half diagonal in pixels, with margin.
 float k=blockSize*.70711*2.0/(m*uParam_size*2.45)*1.2;
 float tc=max(0.0,entry-.15);
 for(int i=0;i<112;i++){
  float dc=metalForm(ro+tc*rd)-tc*k;
  if(dc<.003)break;
  tc+=dc*.44;if(tc>exitAt+.1)break;
 }
 value=vec4(max(0.0,tc-.12),0.0,0.0,1.0);
}
